// Arquivo completo e redesenhado para: src/components/MeusPetsScreen.js

import React, { useState, useEffect } from 'react';
import axios from '../api/axios';
import PetCard from './PetCard';
import PetHistoryModal from './PetHistoryModal';
import { useNavigate } from 'react-router-dom'; // Importa o hook para navegação

// Objeto de estilos redesenhado para alinhar com a identidade visual do app
const styles = {
    // Container principal que imita o layout das telas de login/perfil
    container: {
        minHeight: 'calc(100vh - 120px)', // Ajusta a altura para preencher a tela
        display: 'flex',
        alignItems: 'flex-start', // Alinha ao topo
        justifyContent: 'center',
        padding: '2rem',
        backgroundColor: '#f5f5f5', // Um fundo suave
    },
    // Card principal que envolve todo o conteúdo
    contentWrapper: {
        width: '100%',
        maxWidth: '1200px',
        backgroundColor: 'white',
        padding: '2rem',
        borderRadius: '12px',
        boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
    },
    header: {
        textAlign: 'center',
        marginBottom: '2rem',
        borderBottom: '1px solid #eee',
        paddingBottom: '1rem',
    },
    h1: {
        color: '#333',
        margin: '0',
    },
    subHeader: {
        color: '#666',
        marginTop: '0.5rem',
    },
    petsGrid: {
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
        gap: '1.5rem',
    },
    message: {
        textAlign: 'center',
        padding: '3rem 1rem',
        fontSize: '1.2rem',
        color: '#555',
    },
    // Estilo para a seção "Nenhum pet cadastrado"
    noPetsContainer: {
        textAlign: 'center',
        padding: '3rem 1rem',
    },
    noPetsText: {
        fontSize: '1.1rem',
        color: '#666',
        marginBottom: '1.5rem',
    },
    // Botão com o estilo principal do app
    button: {
        backgroundColor: '#4a9b8e',
        color: 'white',
        border: 'none',
        padding: '0.75rem 1.5rem',
        borderRadius: '8px',
        fontSize: '1rem',
        fontWeight: '600',
        cursor: 'pointer',
        transition: 'all 0.3s ease',
    }
};

function MeusPetsScreen() {
    const [pets, setPets] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [selectedPet, setSelectedPet] = useState(null);
    const navigate = useNavigate(); // Hook para poder navegar para outras telas

    useEffect(() => {
        const fetchPets = async () => {
            setLoading(true);
            try {
                const token = localStorage.getItem('token');
                const response = await axios.get('/pets', {
                    headers: { 'Authorization': `Bearer ${token}` }
                });
                setPets(response.data);
            } catch (err) {
                setError('Não foi possível buscar os pets. Tente novamente mais tarde.');
            } finally {
                setLoading(false);
            }
        };
        fetchPets();
    }, []);

    const handleUpdatePet = (updatedPet) => {
        setPets(pets.map(pet => (pet.id === updatedPet.id ? updatedPet : pet)));
    };

    const handleNavigateToCadastro = () => {
        navigate('/cadastrar-pet');
    };

    const renderContent = () => {
        if (loading) return <div style={styles.message}>Carregando seus pets...</div>;
        if (error) return <div style={{...styles.message, color: '#dc3545'}}>{error}</div>;

        if (pets.length === 0) {
            return (
                <div style={styles.noPetsContainer}>
                    <p style={styles.noPetsText}>Você ainda não cadastrou nenhum companheiro.</p>
                    <button style={styles.button} onClick={handleNavigateToCadastro}>
                        🐾 Cadastrar Meu Primeiro Pet
                    </button>
                </div>
            );
        }

        return (
            <div style={styles.petsGrid}>
                {pets.map(pet => (
                    <PetCard
                        key={pet.id}
                        pet={pet}
                        onViewHistory={() => setSelectedPet(pet)}
                        onPetUpdated={handleUpdatePet}
                    />
                ))}
            </div>
        );
    };

    return (
        <div style={styles.container}>
            <div style={styles.contentWrapper}>
                <div style={styles.header}>
                    <h1 style={styles.h1}>Meus Pets</h1>
                    <p style={styles.subHeader}>Gerencie as informações e o histórico dos seus companheiros.</p>
                </div>
                
                {renderContent()}
                
                {selectedPet && (
                    <PetHistoryModal
                        pet={selectedPet}
                        onClose={() => setSelectedPet(null)}
                    />
                )}
            </div>
        </div>
    );
}

export default MeusPetsScreen;
